  'help.send': 'Saada pilet',
  'help.ticketSent': 'Pilet saadetud!',
  'help.ticketSentDesc': 'Oleme teie taotluse saanud. Meie meeskond vastab e-posti teel 24 tunni jooksul.',
  'help.close': 'Sulge',
  'help.ticketError': 'Piletit ei õnnestunud saata. Proovige uuesti.',
  'help.type.cant_login': 'Ei saa sisse logida',
  'help.type.email_issue': 'E-posti probleem',
  'help.type.security': 'Turvalisus',
  'help.type.other': 'Muu',
  'help.faq.cantLogin.q': 'Ei saa oma kontole juurde',
  'help.faq.cantLogin.a': 'Kontrollige, kas kasutate õiget e-posti ja parooli. Kui olete parooli unustanud, klõpsake sisselogimise ekraanil "Unustasite parooli?". Kui probleem püsib, looge tugipilet.',
  'help.faq.notReceiving.q': 'Ei saa e-kirju',
  'help.faq.notReceiving.a': 'Kontrollige esmalt rämpsposti kausta. Veenduge, et teie salvestus ei oleks täis. Kui probleem püsib, kinnitage, et saatja aadress on õige ja looge pilet.',
  'help.faq.cantSend.q': 'Ei saa e-kirju saata',
  'help.faq.cantSend.a': 'Kontrollige oma internetiühendust ja veenduge, et saaja aadress on õige. Veenduge, et manused ei ületaks 25MB. Proovige mõne minuti pärast uuesti.',
  'help.faq.forgotPassword.q': 'Unustasin oma parooli',
  'help.faq.forgotPassword.a': 'Sisselogimise ekraanil klõpsake "Unustasite parooli?" ja järgige juhiseid, et lähtestada oma parool taastamiskirja kaudu.',
  'help.faq.accountSecurity.q': 'Arvan, et minu konto on ohustatud',
  'help.faq.accountSecurity.a': 'Muuda oma parooli kohe. Kontrollige saadetud kaustas, kas olete saatnud sõnumeid, mida te ei saatnud. Aktiveerige kahefaktoriline autentimine Seaded > Turvalisus. Kui vajalik, looge kiire pilet.',
  'help.faq.appAccess.q': 'Kuidas pääsen rakendusele mobiilis?',
  'help.faq.appAccess.a': 'Saate Chatyy juurde pääseda brauseris chatyy.com.br või laadida alla meie rakenduse oma seadme rakenduste poest.',
  'privacy.title': 'Privaatsuspoliitika',
  'privacy.subtitle': 'Kuidas me kaitseme ja käsitleme teie andmeid',
  'privacy.lastUpdated': 'Viimati uuendatud: Märts 2026',
  'privacy.dataCollection.title': 'Andmete kogumine',
  'privacy.dataCollection.body': 'Kogume ainult teenuse jaoks vajalikke andmeid: teie nimi, e-posti aadress ja saadetud ning saadud sõnumite sisu. Me ei müü ega jaga teie isikuandmeid kolmandatele osapooltele turunduseesmärkidel.',
  'privacy.dataUsage.title': 'Kuidas me kasutame teie andmeid',
  'privacy.dataUsage.body': 'Teie andmeid kasutatakse ainult e-posti teenuse toimimiseks ja parandamiseks, sealhulgas sõnumite edastamine, rämpsposti filtreerimine, IA funktsioonid (teie nõusolekul) ja konto turvalisus.',
  'privacy.dataSecurity.title': 'Andmete turvalisus',
  'privacy.dataSecurity.body': 'Kasutame tööstusstandardi krüpteerimist (TLS/SSL) kõigi andmete edastamisel ja salvestamisel. Sessioonid on kaitstud krüpteeritud tokenitega ja CSRF kaitsega. Kontrollime regulaarselt oma turvapraktikaid.',
  'privacy.cookies.title': 'Küpsised ja kohalik salvestamine',
  'privacy.cookies.body': 'Kasutame hädavajalikke küpsiseid ja kohalikku salvestamist, et hoida teie sessiooni, meeles pidada teie eelistusi (teema, keel) ja pakkuda sujuvat kogemust. Me ei kasuta kolmandate osapoolte jälgimisküpsiseid.',
  'privacy.thirdParties.title': 'Kolmandate osapoolte teenused',
  'privacy.thirdParties.body': 'V võime kasutada kolmandate osapoolte teenuseid spetsiifiliste funktsioonide jaoks, nagu IA (Anthropic Claude) ja push-teated. Need teenused järgivad oma privaatsuspoliitikat ja töötlevad ainult minimaalset vajalikku andmeid.',
  'privacy.rights.title': 'Teie õigused',
  'privacy.rights.body': 'Teil on õigus igal ajal oma isikuandmetele juurde pääseda, neid parandada, eksportida või kustutada. Saate oma andmeid hallata seadetes või meie tugiteenusega ühendust võttes.',
  'privacy.contact.title': 'Võtke meiega ühendust',
  'privacy.contact.body': 'Privaatsuse või andmete taotluste küsimuste korral võtke ühendust privacy@chatyy.com.br. Vastame 30 päeva jooksul.',
  'terms.title': 'Teenuse tingimused',
  'terms.subtitle': 'Chatyy kasutamise juhised',
  'terms.lastUpdated': 'Viimati uuendatud: Märts 2026',
  'terms.acceptance.title': 'Tingimuste aktsepteerimine',
  'terms.acceptance.body': 'Chatyy juurde pääsemise või kasutamisega nõustute nende teenuse tingimustega. Kui te ei nõustu mõne osa nende tingimustega, ärge kasutage teenust.',
  'terms.services.title': 'Teenuste kirjeldus',
  'terms.services.body': 'Chatyy pakub e-posti suhtluse teenuseid, sealhulgas e-kirjade saatmist, vastuvõtmist ja haldamist, samuti IA funktsioone, kalendri integreerimist ja videokonverentse.',
  'terms.accounts.title': 'Kasutajakontod',
  'terms.accounts.body': 'Te olete vastutav oma volituste turvalisuse eest. Ärge jagage oma parooli ega lubage volitamata juurdepääsu oma kontole. Teenuse kasutamiseks peate olema vähemalt 13-aastane.',
  'terms.conduct.title': 'Lubatud kasutamine',
  'terms.conduct.body': 'Nõustute, et ei kasuta teenust rämpsposti, pahavara, petuskeemide või muu ebaseadusliku sisu saatmiseks. Ärge proovige teiste kasutajate kontodele juurde pääseda ega teenuse infrastruktuuri katkestada.',
  'terms.content.title': 'Sisu omandiõigus',
  'terms.content.body': 'Te säilitada kogu sisu omandiõiguse, mille loote ja saadate teenuse kaudu. Me ei nõua omandiõigust teie e-kirjade või manuste üle. Me võime sisu töödelda vastavalt teenuse osutamiseks vajalikele vajadustele.',
  'terms.limitation.title': 'Vastutuse piiramine',
  'terms.limitation.body': 'Chatyy pakutakse "nagu on". Püüame tagada 99,9% kättesaadavust, kuid ei garanteeri katkematut teenust. Me ei vastuta kaudsete, juhuslike või tagajärgede eest, mis tulenevad teenuse kasutamisest.',
  'terms.termination.title': 'Konto lõpetamine',
  'terms.termination.body': 'Me võime peatada või lõpetada kontod, mis rikuvad neid tingimusi. Saate oma konto igal ajal Seadetes kustutada. Pärast lõpetamist kustutatakse teie andmed 30 päeva jooksul.',
  'terms.changes.title': 'Muudatused tingimustes',
  'terms.changes.body': 'Võime neid tingimusi perioodiliselt uuendada. Teavitame olulistest muudatustest e-posti või rakenduse teate kaudu. Pärast muudatusi jätkuv kasutamine tähendab tingimuste aktsepteerimist.',
